import{_ as t,o as a,c as d,ag as s}from"./chunks/framework.DaCm-iTo.js";const k=JSON.parse('{"title":"CoreLib 动作","description":"","frontmatter":{},"headers":[],"relativePath":"modules/codex/corelib-actions.md","filePath":"modules/codex/corelib-actions.md","lastUpdated":null}'),o={name:"modules/codex/corelib-actions.md"};function i(c,e,n,l,h,p){return a(),d("div",null,[...e[0]||(e[0]=[s(`<h1 id="corelib-动作" tabindex="-1">CoreLib 动作 <a class="header-anchor" href="#corelib-动作" aria-label="Permalink to &quot;CoreLib 动作&quot;">​</a></h1><p>EmakiCodex 启用后会向 CoreLib 动作注册表追加成就管理段。它们可用于其他模块的奖励、触发器或管道模板中，用来授予、撤销、重推、重置 Codex 图鉴节点，或显示只存在于客户端的成就 Toast。</p><blockquote><p>本页只记录 EmakiCodex 注册的段；CoreLib 自带通用段见 <a href="./../corelib/actions.html">CoreLib 动作系统</a>。</p></blockquote><p>六个段的分类都是 <code>codex</code>，目标要求都是 <code>REQUIRED_ENTITY</code>，非玩家目标会跳过。旧的 <code>showachievementtoast</code> 现在写作 <code>codex_show_toast</code>；其余五个段的 id 未变。</p><p>「作用于谁」由 source 决定，不再有 <code>target</code> 参数：作用于执行者自己写 <code>self</code>，指定玩家用 <code>player_by_name</code>。</p><h2 id="段总览" tabindex="-1">段总览 <a class="header-anchor" href="#段总览" aria-label="Permalink to &quot;段总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>段 ID</th><th>说明</th></tr></thead><tbody><tr><td><code>codex_grant_advancement</code></td><td>授予目标玩家一个 Codex 节点。</td></tr><tr><td><code>codex_revoke_advancement</code></td><td>撤销目标玩家一个 Codex 节点。</td></tr><tr><td><code>codex_resync_advancement</code></td><td>向目标玩家重推 Codex Advancement 数据。</td></tr><tr><td><code>codex_reset_page</code></td><td>撤销目标玩家某一页下的所有已注册节点。</td></tr><tr><td><code>codex_reset_all</code></td><td>撤销目标玩家所有已注册 Codex 节点。</td></tr><tr><td><code>codex_show_toast</code></td><td>向目标玩家显示客户端成就 Toast，不注册或授予真实进度。</td></tr></tbody></table><h2 id="codex-grant-advancement" tabindex="-1">codex_grant_advancement <a class="header-anchor" href="#codex-grant-advancement" aria-label="Permalink to &quot;codex_grant_advancement&quot;">​</a></h2><p>授予目标玩家一个 EmakiCodex 成就节点。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>必填</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>advancement</code></td><td>STRING</td><td>是</td><td>—</td><td>成就 ID。可写 <code>page/node</code>，也可写完整 NamespacedKey。</td></tr></tbody></table><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | codex_grant_advancement advancement=example/first_step&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;player_by_name name=Steve | codex_grant_advancement advancement=emakicodex:example/challenge&#39;</span></span></code></pre></div><p><code>advancement</code> 为空时以 <code>INVALID_CONFIG</code> 失败。节点未注册与玩家已完成该节点合并报为一个 <code>REJECTED</code>：成就服务的返回值区分不出这两种情况，在这里细分诊断只会是猜测。</p><p>成功时输出 <code>advancement</code> 与 <code>target</code>。</p><h2 id="codex-revoke-advancement" tabindex="-1">codex_revoke_advancement <a class="header-anchor" href="#codex-revoke-advancement" aria-label="Permalink to &quot;codex_revoke_advancement&quot;">​</a></h2><p>撤销目标玩家一个 EmakiCodex 成就节点。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>必填</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>advancement</code></td><td>STRING</td><td>是</td><td>—</td><td>成就 ID。可写 <code>page/node</code>，也可写完整 NamespacedKey。</td></tr></tbody></table><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | codex_revoke_advancement advancement=example/first_step&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;player_by_name name=Steve | codex_revoke_advancement advancement=emakicodex:example/challenge&#39;</span></span></code></pre></div><p><code>advancement</code> 为空时以 <code>INVALID_CONFIG</code> 失败；节点未注册或玩家尚未完成该节点时以 <code>REJECTED</code> 失败。</p><h2 id="codex-resync-advancement" tabindex="-1">codex_resync_advancement <a class="header-anchor" href="#codex-resync-advancement" aria-label="Permalink to &quot;codex_resync_advancement&quot;">​</a></h2><p>向目标玩家重推当前已注册的 Codex Advancement 数据。无参数。</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | codex_resync_advancement&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;player_by_name name=Steve | codex_resync_advancement&#39;</span></span></code></pre></div><p>适用场景：</p><ul><li>配置重载后，希望不要求玩家重登就刷新客户端成就树。</li><li>自定义流程里需要在授予或重置后主动刷新显示。</li></ul><p>这个段依赖 PacketEvents：网关不存在或当前不支持重推时以 <code>MISSING_CONTEXT</code> 失败，重推本身失败时以 <code>INTERNAL_ERROR</code> 失败。成功时输出 <code>target</code> 与 <code>player</code>。</p><h2 id="codex-reset-page" tabindex="-1">codex_reset_page <a class="header-anchor" href="#codex-reset-page" aria-label="Permalink to &quot;codex_reset_page&quot;">​</a></h2><p>撤销目标玩家某一页下所有已注册的 Codex 节点。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>必填</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>page</code></td><td>STRING</td><td>是</td><td>—</td><td>成就页 ID，例如 <code>example</code>。</td></tr></tbody></table><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | codex_reset_page page=example&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;player_by_name name=Steve | codex_reset_page page=example&#39;</span></span></code></pre></div><p>节点按注册顺序的反向逐个撤销，也就是先子节点后父节点：先撤父节点会让客户端显示已经不存在的进度。</p><p><code>page</code> 为空时以 <code>INVALID_CONFIG</code> 失败；该页没有匹配到任何已注册节点时按跳过处理。成功时输出 <code>target</code>、<code>player</code>、<code>mode</code>、<code>page</code>、<code>nodes</code>、<code>revoked</code>。</p><h2 id="codex-reset-all" tabindex="-1">codex_reset_all <a class="header-anchor" href="#codex-reset-all" aria-label="Permalink to &quot;codex_reset_all&quot;">​</a></h2><p>撤销目标玩家所有当前已注册的 Codex 节点。无参数。</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | codex_reset_all&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;player_by_name name=Steve | codex_reset_all&#39;</span></span></code></pre></div><p>撤销顺序与 <code>codex_reset_page</code> 相同。成功时输出 <code>mode=reset_all</code>、<code>nodes</code> 与 <code>revoked</code>，<code>page</code> 为空字符串。</p><h2 id="codex-show-toast" tabindex="-1">codex_show_toast <a class="header-anchor" href="#codex-show-toast" aria-label="Permalink to &quot;codex_show_toast&quot;">​</a></h2><p>向目标玩家显示客户端成就 Toast，不注册、不授予、不保存真实进度。Toast 是一个通过封包推送的假成就，稍后再撤回，所以撤回是被调度出去的而不是立即执行。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>必填</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>title</code></td><td>STRING</td><td>是</td><td>—</td><td>Toast 标题，支持 MiniMessage。</td></tr><tr><td><code>description</code></td><td>STRING</td><td>否</td><td><code>&quot;&quot;</code></td><td>Toast 描述文本，支持 MiniMessage。</td></tr><tr><td><code>icon</code></td><td>STRING</td><td>否</td><td><code>minecraft-book</code></td><td>Toast 图标物品来源；支持 CoreLib 物品来源短写，无法解析时回退为原版材质。</td></tr><tr><td><code>frame</code></td><td>STRING</td><td>否</td><td><code>task</code></td><td>Toast 框体：<code>task</code>、<code>goal</code> 或 <code>challenge</code>。</td></tr><tr><td><code>id</code></td><td>STRING</td><td>否</td><td><code>&quot;&quot;</code></td><td>客户端临时进度 ID；留空时随机生成，最终命名空间为 <code>emakicodex:toast/&lt;id&gt;</code>。</td></tr><tr><td><code>remove_delay</code></td><td>DURATION</td><td>否</td><td><code>20t</code></td><td>发送后移除临时进度包的延迟。</td></tr></tbody></table><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | codex_show_toast title=&quot;&lt;gold&gt;图鉴发现&lt;/gold&gt;&quot; description=&quot;&lt;gray&gt;新的篇章已点亮&lt;/gray&gt;&quot; icon=minecraft-book frame=goal id=codex_discovery remove_delay=20t&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | codex_show_toast title=&quot;&lt;yellow&gt;解锁新配方&lt;/yellow&gt;&quot;&#39;</span></span></code></pre></div><p>同一个 <code>id</code> 反复触发时，旧的撤回任务不会误删新推送的 Toast：撤回带有一次性令牌，令牌在重载后依然有效，所以重载前调度的撤回能识别出自己那份 Toast 已被替换。</p><h2 id="使用提示" tabindex="-1">使用提示 <a class="header-anchor" href="#使用提示" aria-label="Permalink to &quot;使用提示&quot;">​</a></h2><ul><li>这些段只处理在线玩家。</li><li>节点是否可见、父子关系、toast、广播与完成动作仍由 <code>advancements/*.yml</code> 控制。</li><li><code>codex_resync_advancement</code> 与 <code>codex_show_toast</code> 需要 PacketEvents；授予、撤销、重置段不依赖 PacketEvents。</li><li>相关服务尚未就绪时，段以 <code>MISSING_CONTEXT</code> 失败而不是静默跳过。</li></ul>`,41)])])}const g=t(o,[["render",i]]);export{k as __pageData,g as default};
